const TitleMotionEntrance = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 1280;
  const H = item.height || 720;

  const title = p.title || '全新登场';
  const subtitle = p.subtitle || 'A NEW CHAPTER BEGINS';
  const bg = p.bg || '#0E1116';
  const blockColor = p.blockColor || '#E63946';
  const titleColor = p.titleColor || '#FFFFFF';
  const subtitleColor = p.subtitleColor || '#C9D2DC';

  const T = (s) => s * fps;
  const t0 = 0.5; // 片头标题入场不早于 0.3s，取 0.5s 留呼吸

  // 入场 helper（opacity 0→1 + translateY）
  const enter = (start, dur, dist, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.exp) });
    return { opacity: k, transform: `translateY(${(1 - k) * dist}px)` };
  };

  // 色块衬底：入场下沉 40→0 + 淡入，出场纯淡出
  const blockIn = interpolate(frame, [T(t0), T(t0 + 0.35)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.exp) });
  const blockY = interpolate(frame, [T(t0), T(t0 + 0.35)], [40, 0],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.exp) });
  const exitFade = interpolate(frame, [T(3.0), T(3.3)], [1, 0],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const blockOpacity = blockIn * exitFade;

  // 逐字入场（0.05s stagger）
  const chars = String(title).split('');
  const charItems = chars.map((ch, i) => ({ ...enter(t0 + i * 0.05, 0.3, 0), ch }));

  // 副标题整体上浮淡入
  const subStyle = enter(t0, 0.35, 20);

  const mainSize = H * 0.15;
  const blockH = mainSize * 1.84;
  const blockW = W * 0.62;
  const sans = "'Noto Sans SC', 'PingFang SC', sans-serif";

  return (
    <div style={{ width: W, height: H, position: 'relative', overflow: 'hidden', background: bg, fontFamily: sans }}>
      <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', paddingLeft: W * 0.09 }}>
        <div style={{ position: 'relative' }}>
          {/* 色块衬底（垫底层） */}
          <div style={{
            position: 'absolute', left: -W * 0.02, top: -(blockH - mainSize * 1.15) / 2,
            width: blockW, height: blockH, background: blockColor,
            opacity: blockOpacity, transform: `translateY(${blockY}px)`
          }} />
          {/* 主标题（逐字） */}
          <div style={{ position: 'relative', fontSize: mainSize, fontWeight: 900, lineHeight: 1.15, color: titleColor, whiteSpace: 'pre' }}>
            {charItems.map((c, i) => (
              <span key={i} style={{ display: 'inline-block', opacity: c.opacity * exitFade, transform: c.transform }}>{c.ch === ' ' ? '\u00A0' : c.ch}</span>
            ))}
          </div>
          {/* 副标题 */}
          <div style={{
            position: 'relative', marginTop: mainSize * 0.12, fontSize: H * 0.055,
            color: subtitleColor, letterSpacing: '0.18em',
            opacity: subStyle.opacity * exitFade, transform: subStyle.transform
          }}>{subtitle}</div>
        </div>
      </div>
    </div>
  );
};

const KineticTypeIntro = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 1280;
  const H = item.height || 720;

  const hook = [p.hook1 || 'What if', p.hook2 || 'great coffee', p.hook3 || 'brewed itself?'];
  const kicker = p.kicker || 'A FILM ABOUT SLOWNESS';
  const pillars = [p.pillar1 || 'SINGLE ORIGIN', p.pillar2 || 'HAND POURED', p.pillar3 || 'SMALL BATCH'];
  const statValue = p.statValue || '92';
  const statLabel = String(p.statLabel || 'cupping score').toUpperCase();
  const outroWords = String(p.outroName || 'MOUNTAIN COFFEE').split(' ');
  const outroTagline = String(p.outroTagline || 'slow down, drink well').toUpperCase();
  const bg = p.bg || '#101418';
  const ink = p.ink || '#F5F7FA';
  const accent = p.accent || '#6CF3C0';
  const muted = p.muted || '#9AA4B2';

  const T = (s) => s * fps;
  const enter = (start, dur, dist, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.exp) });
    return { opacity: k, transform: `translateY(${(1 - k) * dist}px)` };
  };
  const enterX = (start, dur, dist, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.poly(3)) });
    return { opacity: k, transform: `translateX(${(1 - k) * dist}px)` };
  };
  const growX = (start, dur, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.poly(2)) });
    return { transform: `scaleX(${k})` };
  };
  const fade = (start, dur) => interpolate(frame, [T(start), T(start + dur)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  // 四幕显隐窗口
  const act1 = interpolate(frame, [T(0), T(0.1), T(2.0), T(2.05)], [0, 1, 1, 0],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const act2 = interpolate(frame, [T(2.2), T(2.3), T(4.5), T(4.55)], [0, 1, 1, 0],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const act3 = interpolate(frame, [T(4.7), T(4.8), T(6.5), T(6.55)], [0, 1, 1, 0],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const act4 = interpolate(frame, [T(6.7), T(6.8)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  // 幕间白场闪切
  const wipe = [1.95, 4.45, 6.45].reduce((acc, s) => Math.max(acc, interpolate(frame,
    [T(s), T(s + 0.12), T(s + 0.3)], [0, 1, 0],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' })), 0);

  const hookLines = hook.map((line, i) => ({ ...enter(0.15 + i * 0.22, 0.55, 90), line, main: i === 1 }));
  const kickerStyle = { opacity: fade(1.25, 0.4) };
  const pillarRule = growX(2.45, 0.5);
  const pillarItems = pillars.map((w, i) => ({ ...enterX(2.55 + i * 0.3, 0.5, -80), word: w, first: i === 0 }));
  const statPop = interpolate(frame, [T(4.95), T(5.55)], [0.6, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.exp) });
  const statLabelStyle = enter(5.35, 0.45, 26, Easing.out(Easing.poly(3)));
  const outroWordItems = outroWords.map((w, i) => ({ ...enter(6.95 + i * 0.12, 0.5, 40), word: w }));
  const outroRule = growX(7.35, 0.45);
  const outroTaglineStyle = { opacity: fade(7.55, 0.4) };

  const serif = "Georgia, 'Noto Serif SC', serif";

  return (
    <div style={{ width: W, height: H, position: 'relative', background: bg, color: ink, fontFamily: serif, overflow: 'hidden' }}>
      {/* 幕1 钩子 */}
      <div style={{ position: 'absolute', inset: 0, opacity: act1, display: 'flex', flexDirection: 'column', justifyContent: 'center', padding: W * 0.1 }}>
        {hookLines.map((h, i) => (
          <div key={i} style={{ fontSize: h.main ? 108 : 76, lineHeight: 1.08, fontWeight: 700, color: h.main ? accent : ink, letterSpacing: '-0.01em', opacity: h.opacity, transform: h.transform }}>
            {h.line}
          </div>
        ))}
        <div style={{ marginTop: 28, fontSize: 20, color: muted, letterSpacing: '0.35em', opacity: kickerStyle.opacity }}>{kicker}</div>
      </div>

      {/* 幕2 要点 */}
      <div style={{ position: 'absolute', inset: 0, opacity: act2, display: 'flex', flexDirection: 'column', justifyContent: 'center', padding: W * 0.12 }}>
        <div style={{ width: 72, height: 4, background: accent, marginBottom: 34, transformOrigin: 'left center', ...pillarRule }} />
        {pillarItems.map((pl, i) => (
          <div key={i} style={{ fontSize: 62, fontWeight: 700, letterSpacing: '0.02em', marginBottom: 18, color: pl.first ? accent : ink, opacity: pl.opacity, transform: pl.transform }}>
            {pl.word}
          </div>
        ))}
      </div>

      {/* 幕3 数字 */}
      <div style={{ position: 'absolute', inset: 0, opacity: act3, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ fontSize: 230, fontWeight: 700, color: accent, lineHeight: 1, fontVariantNumeric: 'tabular-nums', opacity: statPop, transform: `scale(${statPop})` }}>{statValue}</div>
        <div style={{ marginTop: 18, fontSize: 26, letterSpacing: '0.3em', color: muted, opacity: statLabelStyle.opacity, transform: statLabelStyle.transform }}>{statLabel}</div>
      </div>

      {/* 幕4 落版 */}
      <div style={{ position: 'absolute', inset: 0, opacity: act4, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ display: 'flex' }}>
          {outroWordItems.map((w, i) => (
            <span key={i} style={{ fontSize: 64, fontWeight: 700, letterSpacing: '0.08em', margin: '0 14px', opacity: w.opacity, transform: w.transform }}>{w.word}</span>
          ))}
        </div>
        <div style={{ width: 160, height: 3, background: accent, margin: '26px 0', transformOrigin: 'center center', ...outroRule }} />
        <div style={{ fontSize: 22, color: muted, letterSpacing: '0.28em', opacity: outroTaglineStyle.opacity }}>{outroTagline}</div>
      </div>

      {/* 白场闪切层 */}
      <div style={{ position: 'absolute', inset: 0, background: '#FFFFFF', opacity: wipe, zIndex: 30 }} />
    </div>
  );
};

const ShadowCut = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 1280;
  const H = item.height || 720;

  const caseNo = p.caseNo || 'CASE FILE 0917 · CONFIDENTIAL';
  const headline = p.headline || '内鬼找到了';
  const detail = p.detail || '异常访问始于 87 天前 · 三级权限 · 单点突破';
  const verdict = p.verdict || '已锁定';
  const bg = p.bg || '#0A0A0A';
  const ink = p.ink || '#F5F5F5';
  const gray = p.gray || '#3A3A3A';
  const red = p.red || '#C1121F';
  const muted = p.muted || '#777777';

  const t = frame / fps;
  const vertical = H > W;

  const T = (s) => s * fps;
  const enter = (start, dur, dist, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.exp) });
    return { opacity: k, transform: `translateY(${(1 - k) * dist}px)` };
  };
  const growX = (start, dur, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.poly(2)) });
    return { transform: `scaleX(${k})` };
  };

  // 聚光极缓漂移（唯一环境动效）
  const spotX = 0.5 + 0.02 * Math.sin(t * 0.5);
  const spotY = 0.45 + 0.015 * Math.cos(t * 0.4);

  const caseNoStyle = enter(0.2, 0.5, 8, Easing.out(Easing.sin));
  const headlineK = interpolate(frame, [T(1.1), T(1.8)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.exp) });
  const detailStyle = enter(1.9, 0.45, 10, Easing.out(Easing.sin));
  const verdictK = interpolate(frame, [T(2.6), T(2.82)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.in(Easing.poly(4)) });
  const redline = growX(2.78, 0.18, Easing.out(Easing.poly(3)));
  const stampK = interpolate(frame, [T(3.0), T(3.3)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.poly(2)) });
  const stampRotate = -2 - 4 * (1 - stampK);

  const display = "'Bebas Neue', 'Noto Serif SC', serif";
  const sans = "'Inter', 'Noto Sans SC', sans-serif";

  return (
    <div style={{ width: W, height: H, background: bg, position: 'relative', overflow: 'hidden', boxSizing: 'border-box', fontFamily: sans }}>
      <div style={{ position: 'absolute', left: 0, top: 0, right: 0, bottom: 0, background: `radial-gradient(ellipse ${W * 0.55}px ${H * 0.6}px at ${spotX * 100}% ${spotY * 100}%, #1E1E1E 0%, #0A0A0A 68%)` }} />
      <div style={{ position: 'absolute', left: 0, top: 0, right: 0, bottom: 0, background: `radial-gradient(ellipse ${W * 0.42}px ${H * 0.5}px at ${spotX * 100}% ${spotY * 100}%, transparent 40%, #000000C0 100%)` }} />
      <div style={{ position: 'absolute', left: W * 0.08, top: H * 0.16, fontSize: H * 0.022, letterSpacing: W * 0.009, color: muted, opacity: caseNoStyle.opacity, transform: caseNoStyle.transform }}>{caseNo}</div>
      <div style={{ position: 'absolute', left: W * 0.08, top: H * 0.36, right: W * 0.1 }}>
        <div style={{ fontFamily: display, fontSize: vertical ? W * 0.14 : H * 0.19, color: ink, lineHeight: 1.05, letterSpacing: W * 0.003, textShadow: `0 ${H * 0.01}px ${H * 0.03}px #000`, opacity: headlineK, transform: `scale(${1.05 - 0.05 * headlineK})` }}>{headline}</div>
        <div style={{ marginTop: H * 0.04, fontSize: H * 0.028, color: gray, letterSpacing: W * 0.002, opacity: detailStyle.opacity, transform: detailStyle.transform }}>{detail}</div>
      </div>
      <div style={{ position: 'absolute', left: W * 0.08, bottom: H * 0.24, width: W * 0.34, height: Math.max(2, H * 0.004), background: red, transformOrigin: 'left center', ...redline }} />
      <div style={{ position: 'absolute', left: W * 0.08, bottom: H * 0.13, display: 'inline-block', fontFamily: display, fontSize: H * 0.075, color: red, letterSpacing: W * 0.006, opacity: verdictK, transform: `scale(${1.5 - 0.5 * verdictK})` }}>{verdict}</div>
      <div style={{ position: 'absolute', right: W * 0.09, bottom: H * 0.14, border: `${Math.max(1, H * 0.003)}px solid ${muted}`, color: muted, fontSize: H * 0.02, letterSpacing: W * 0.005, padding: `${H * 0.008}px ${W * 0.012}px`, opacity: stampK, transform: `rotate(${stampRotate}deg)` }}>EVIDENCE SEALED</div>
    </div>
  );
};

const DeconstructedGlitch = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 1280;
  const H = item.height || 720;

  const tag = p.tag || 'SECURITY BRIEFING';
  const headline = p.headline || '零信任防线';
  const sub = p.sub || '攻击面收敛 · 实时阻断 · 全链路审计';
  const issue = p.issue || 'VOL.07 — 2026';
  const bg = p.bg || '#17181B';
  const ink = p.ink || '#F0F0F0';
  const accent = p.accent || '#D4501E';
  const cold = p.cold || '#8FA3B0';
  const line = p.line || '#2A2C31';

  const t = frame / fps;
  const vertical = H > W;
  const scan = 0.05 + 0.03 * (1 + Math.sin(t * 2.2)) / 2;
  const heavy = '"Archivo Black", "ZCOOL QingKe HuangYou", sans-serif';
  const sans = '"Inter", "Noto Sans SC", sans-serif';
  const titleSize = vertical ? W * 0.155 : H * 0.2;

  const T = (s) => s * fps;
  const kAt = (start, dur, ease) => interpolate(frame, [T(start), T(start + dur)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });

  const scanFade = kAt(0.12, 0.18, Easing.out(Easing.poly(1)));
  const coldK = kAt(0.2, 0.3, Easing.in(Easing.poly(4)));
  const warmK = kAt(0.24, 0.26, Easing.in(Easing.poly(4)));
  const headK = kAt(0.5, 0.22, Easing.out(Easing.poly(3)));
  const tagK = kAt(0.8, 0.3, Easing.out(Easing.poly(2)));
  const issueK = kAt(0.88, 0.3, Easing.out(Easing.poly(2)));
  const barK = kAt(1.3, 0.4, Easing.inOut(Easing.poly(3)));
  const subK = kAt(1.45, 0.35, Easing.out(Easing.sin));

  // 合体后的水平抖动（±x，0.07s×3 往返）
  const jitterX = (() => {
    const st = 0.55, dur = 0.07, n = 3, a = -W * 0.006, b = W * 0.004;
    const tt = t - st;
    if (tt < 0 || tt >= n * dur) return 0;
    const cyc = Math.floor(tt / dur);
    const ph = (tt - cyc * dur) / dur;
    const k = cyc % 2 === 0 ? ph : 1 - ph;
    return a + (b - a) * k;
  })();

  const scanAlpha = Math.round(scan * 255).toString(16).padStart(2, '0');

  return (
    <div style={{ width: W, height: H, background: bg, position: 'relative', overflow: 'hidden', boxSizing: 'border-box', fontFamily: sans }}>
      {/* 扫描线纹理 */}
      <div style={{ position: 'absolute', left: 0, top: 0, right: 0, bottom: 0, background: `repeating-linear-gradient(0deg, ${line}55 0px, ${line}55 1px, transparent 1px, transparent 4px)`, opacity: 0.5 }} />
      <div style={{ position: 'absolute', left: 0, top: 0, right: 0, bottom: 0, background: `repeating-linear-gradient(90deg, ${ink}${scanAlpha} 0px, transparent 2px, transparent 90px)`, opacity: 0.35 * scanFade }} />

      {/* 倾斜破框标题（RGB 错位三层叠印） */}
      <div style={{ position: 'absolute', left: W * (vertical ? 0.08 : 0.06), top: H * 0.3, width: W * 1.1, transform: 'rotate(-2deg)' }}>
        <div style={{ position: 'absolute', left: W * 0.007, top: 0, fontFamily: heavy, fontSize: titleSize, color: cold, opacity: 0.85 * coldK, whiteSpace: 'nowrap', transform: `translateX(${(1 - coldK) * W * 0.06}px)` }}>{headline}</div>
        <div style={{ position: 'absolute', left: -W * 0.006, top: H * 0.004, fontFamily: heavy, fontSize: titleSize, color: accent, opacity: 0.85 * warmK, whiteSpace: 'nowrap', transform: `translateX(${(1 - warmK) * -W * 0.05}px)` }}>{headline}</div>
        <div style={{ position: 'relative', transform: `translateX(${(1 - headK) * -W * 0.03 + jitterX}px)` }}>
          <div style={{ fontFamily: heavy, fontSize: titleSize, color: ink, whiteSpace: 'nowrap', textShadow: `0 ${H * 0.006}px 0 ${bg}`, opacity: headK }}>{headline}</div>
        </div>
      </div>

      {/* 标签与期号 */}
      <div style={{ position: 'absolute', left: W * 0.07, top: H * 0.14, fontSize: H * 0.024, letterSpacing: W * 0.008, color: accent, fontWeight: 700, opacity: tagK, transform: `translateX(${(1 - tagK) * -24}px)` }}>{tag}</div>
      <div style={{ position: 'absolute', right: W * 0.07, top: H * 0.14, fontSize: H * 0.022, letterSpacing: W * 0.005, color: cold, opacity: issueK, transform: `translateX(${(1 - issueK) * 24}px)` }}>{issue}</div>

      {/* 底部锈橙条 */}
      <div style={{ position: 'absolute', left: W * 0.07, bottom: H * 0.2, width: W * 0.24, height: H * 0.012, background: accent, transformOrigin: 'left center', transform: `scaleX(${barK})` }} />
      <div style={{ position: 'absolute', left: W * 0.07, bottom: H * 0.13, fontSize: H * 0.03, color: ink, opacity: 0.85 * subK, letterSpacing: W * 0.003, transform: `translateY(${(1 - subK) * 12}px)` }}>{sub}</div>
    </div>
  );
};

const FolkFrequency = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 720;
  const H = item.height || 1280;

  const kicker = p.kicker || '社区美食节 · 本周末';
  const headline = p.headline || '开吃啦';
  const sub = p.sub || '50 家小摊 · 现做现卖 · 免费入场';
  const badges = [p.badge1 || '烧烤', p.badge2 || '甜品', p.badge3 || '手作'];
  const bg = p.bg || '#FFF6E5';
  const ink = p.ink || '#2A2420';
  const rose = p.rose || '#FF1493';
  const cobalt = p.cobalt || '#0047AB';
  const sun = p.sun || '#FFE000';
  const jade = p.jade || '#009B77';

  const t = frame / fps;
  const vertical = H >= W;
  const round = '"ZCOOL KuaiLe", "Baloo 2", "Noto Sans SC", sans-serif';
  const unit = Math.min(W, H);
  const breathe = 1 + 0.012 * (1 + Math.sin(t * 1.8)) / 2;

  const shapes = ['circle', 'triangle', 'square', 'circle', 'triangle', 'square', 'circle', 'triangle'];
  const shapeColor = (i) => [rose, cobalt, sun, jade][i % 4];

  const T = (s) => s * fps;

  // 弹入 helper：返回 {o 透明度, s 缩放}
  const popIn = (start, dur, from, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.back(2.4)) });
    return { o: k, s: from + (1 - from) * k };
  };
  const fadeUp = (start, dur, dist) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.sin) });
    return { o: k, y: (1 - k) * dist };
  };

  const topShapes = shapes.map((s, i) => ({ ...popIn(0.15 + i * 0.05, 0.4, 0.3), shape: s, color: shapeColor(i) }));
  const kickerStyle = fadeUp(0.3, 0.3, 12);
  const headlinePop = popIn(0.4, 0.55, 0.55);
  const subStyle = fadeUp(0.9, 0.4, 14);
  const badgeItems = badges.map((b, i) => ({ ...popIn(1.05 + i * 0.12, 0.35, 0.5, Easing.out(Easing.back(2))), label: b, color: [rose, cobalt, jade][i % 3] }));
  const bottomShapes = shapes.map((s, i) => ({ ...popIn(1.4 + i * 0.05, 0.4, 0.3), shape: s, color: shapeColor(i + 2) }));

