const SoftSignalMoment = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 1280;
  const H = item.height || 720;

  const quote = p.quote || '睡个好觉，是最被低估的养生。';
