  const amber = p.amber || '#F5A623';
  const sage = p.sage || '#8FAF8C';
  const rose = p.rose || '#C4A3A3';
  const faint = p.faint || '#EFE4CE';

  const t = frame / fps;
  const vertical = H > W;

  const T = (s) => s * fps;
  const enter = (start, dur, dist, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.exp) });
    return { opacity: k, transform: `translateY(${(1 - k) * dist}px)` };
  };
  const pop = (start, dur, from, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [from, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.exp) });
    return { opacity: k, transform: `scale(${k})` };
  };

  // 整卡极缓上下漂移（唯一环境动效）
  const drift = Math.sin(t * 0.7) * H * 0.006;

  const parts = String(quote).split(highlight);
