      <div style={{ position: 'absolute', left: -W * 0.1, bottom: -H * 0.22, width: W * 0.45, height: W * 0.45, borderRadius: '50%', background: `${rose}26` }} />
      <div style={{ position: 'absolute', left: W * 0.12, top: H * 0.2, fontFamily: hand, fontSize: H * 0.08, color: amber, opacity: 0.9 * markStyle.opacity, transform: markStyle.transform }}>“</div>
      <div style={{ position: 'absolute', left: W * 0.12, top: H * 0.34, right: W * 0.14 }}>
        <div style={{ fontFamily: hand, fontSize: quoteSize, color: ink, lineHeight: 1.6, opacity: 0.96 * line1Style.opacity, transform: line1Style.transform }}>
          {before}
          <span style={{ position: 'relative', display: 'inline-block' }}>
            {highlight}
            <svg style={{ position: 'absolute', left: -quoteSize * 0.08, top: -circleH * 0.18 }} width={circleW} height={circleH} viewBox={`0 0 ${circleW} ${circleH}`}>
              <ellipse cx={circleW / 2} cy={circleH / 2} rx={circleW / 2 - 6} ry={circleH / 2 - 6} fill="none" stroke={sage} strokeWidth={quoteSize * 0.06} strokeLinecap="round" strokeDasharray={640} strokeDashoffset={circleDraw} transform={`rotate(-2 ${circleW / 2} ${circleH / 2})`} />
