        <div style={{ marginTop: H * 0.03, fontSize: vertical ? W * 0.185 : H * 0.27, lineHeight: 1, fontWeight: 800, color: ink, letterSpacing: -W * 0.002, fontVariantNumeric: 'tabular-nums', opacity: metricStyle.opacity, transform: metricStyle.transform }}>
