      <svg width={W} height={H} style={{ position: 'absolute', left: 0, top: 0, opacity: webOpacity }} viewBox={`0 0 ${W} ${H}`}>
        <polyline points={poly} fill="none" stroke={line} strokeWidth={1} />
        {dots.slice(0, 6).map((d, i) => (
          <line key={i} x1={d.x} y1={d.y} x2={dots[i + 1].x} y2={dots[i + 1].y} stroke={i % 2 ? cyan : purple} strokeWidth={0.6} opacity={0.5} />
        ))}
      </svg>
      {dots.map((d) => {
        const a = dotAnim[d.i];
        const isCyan = d.i % 3 === 0;
        return (
          <div key={d.i} style={{ position: 'absolute', left: d.x, top: d.y, width: d.r * 2, height: d.r * 2, borderRadius: '50%', background: isCyan ? cyan : ink, opacity: (isCyan ? 0.9 : 0.55) * a.opacity, boxShadow: isCyan ? `0 0 ${d.r * 4}px ${cyan}` : 'none', transform: a.transform }} />
        );
      })}
      <div style={{ position: 'absolute', left: W * (vertical ? 0.09 : 0.08), top: H * 0.30, right: W * 0.08 }}>
        <div style={{ fontSize: H * 0.024, letterSpacing: W * 0.01, color: cyan, fontWeight: 400, opacity: kickerStyle.opacity, transform: kickerStyle.transform }}>{kicker}</div>
        <div style={{ marginTop: H * 0.035, fontSize: vertical ? W * 0.082 : H * 0.12, color: ink, fontWeight: 300, letterSpacing: W * 0.004, lineHeight: 1.25, opacity: headlineStyle.opacity, transform: headlineStyle.transform }}>{headline}</div>
        <div style={{ marginTop: H * 0.05, display: 'flex', alignItems: 'baseline', gap: W * 0.02, opacity: metricStyle.opacity, transform: metricStyle.transform, transformOrigin: 'left bottom' }}>
          <div style={{ fontFamily: '"Inter", sans-serif', fontSize: H * 0.075, fontWeight: 700, color: purple, letterSpacing: W * 0.002, fontVariantNumeric: 'tabular-nums' }}>{metricValue}</div>
          <div style={{ fontSize: H * 0.024, color: muted, letterSpacing: W * 0.008 }}>{metricLabel}</div>
        </div>
      </div>
      <div style={{ position: 'absolute', left: W * (vertical ? 0.09 : 0.08), bottom: H * 0.12, fontSize: H * 0.024, color: muted, letterSpacing: W * 0.003, opacity: footnoteStyle.opacity }}>{footnote}</div>
    </div>
  );
};

const DataBarRace = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 1280;
  const H = item.height || 720;

  const title = p.title || '2026 春季产地销量';
  const unit = p.unit || '袋';
  const items = JSON.parse(p.itemsJson || '[{"label":"耶加雪菲","value":1280},{"label":"瑰夏","value":960},{"label":"曼特宁","value":720},{"label":"肯尼亚 AA","value":540},{"label":"哥伦比亚","value":380}]');
  const bg = p.bg || '#0E1116';
  const ink = p.ink || '#F5F7FA';
  const accent = p.accent || '#6CF3C0';
  const bar = p.bar || '#3A4654';
  const muted = p.muted || '#9AA4B2';

  const T = (s) => s * fps;
  const enter = (start, dur, dist, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.exp) });
    return { opacity: k, transform: `translateY(${(1 - k) * dist}px)` };
  };
  const fade = (start, dur) => interpolate(frame, [T(start), T(start + dur)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const count = (start, dur, target, ease) => Math.round(interpolate(frame, [T(start), T(start + dur)], [0, target],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.poly(2)) }));

  const max = Math.max(...items.map((it) => it.value));
  const barMaxW = W * 0.62;

  const titleStyle = enter(0.1, 0.5, 30, Easing.out(Easing.poly(3)));
  const unitStyle = { opacity: fade(0.45, 0.35) };

  const rowAnim = items.map((it, i) => {
    const start = 0.8 + i * 0.25;
    const targetW = (it.value / max) * barMaxW;
    const barW = interpolate(frame, [T(start), T(start + 0.7)], [0, targetW],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.poly(3)) });
    const val = count(start, 0.7, it.value, Easing.out(Easing.poly(2)));
    const valOpacity = fade(start + 0.1, 0.3);
    return { barW, val, valOpacity, isTop: i === 0 };
  });

  // 冠军强调：accent 描边脉冲（5.6s 亮起 → 5.95s 落到 0.35 定格）
  const ringIn = interpolate(frame, [T(5.6), T(5.9)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.poly(2)) });
  const ringSettle = interpolate(frame, [T(5.95), T(6.45)], [1, 0.35],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.poly(2)) });
  const ringOpacity = Math.min(ringIn, ringSettle);

  const sans = "'Noto Sans SC', Helvetica, sans-serif";

  return (
    <div style={{ width: W, height: H, position: 'relative', background: bg, color: ink, fontFamily: sans, overflow: 'hidden', boxSizing: 'border-box', padding: `${H * 0.1}px ${W * 0.08}px` }}>
      <div style={{ fontSize: 44, fontWeight: 700, letterSpacing: '0.02em', opacity: titleStyle.opacity, transform: titleStyle.transform }}>{title}</div>
      <div style={{ fontSize: 20, color: muted, marginTop: 8, letterSpacing: '0.2em', opacity: unitStyle.opacity }}>单位：{unit}</div>
      <div style={{ marginTop: H * 0.07, display: 'flex', flexDirection: 'column', justifyContent: 'space-between', height: H * 0.52 }}>
        {items.map((it, i) => {
          const a = rowAnim[i];
          return (
            <div key={it.label} style={{ display: 'flex', alignItems: 'center', position: 'relative' }}>
              <div style={{ width: W * 0.16, fontSize: 24, color: a.isTop ? ink : muted, textAlign: 'right', paddingRight: 22, fontWeight: a.isTop ? 700 : 400, boxSizing: 'border-box', whiteSpace: 'nowrap', overflow: 'hidden' }}>
                {it.label}
              </div>
              <div style={{ position: 'relative', flex: 1, height: 44 }}>
                <div style={{ height: '100%', width: a.barW, background: a.isTop ? accent : bar, borderRadius: 3 }} />
                {a.isTop && (
                  <div style={{ position: 'absolute', left: -6, top: -6, bottom: -6, width: (it.value / max) * barMaxW + 12, border: `2px solid ${accent}`, borderRadius: 6, opacity: ringOpacity, pointerEvents: 'none' }} />
                )}
              </div>
              <div style={{ width: W * 0.12, fontSize: 30, marginLeft: 18, fontVariantNumeric: 'tabular-nums', color: a.isTop ? accent : ink, fontWeight: a.isTop ? 700 : 400, opacity: a.valOpacity }}>
                {a.val}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const VelvetStandardDeck = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 1280;
  const H = item.height || 720;

  const eyebrow = p.eyebrow || 'MAISON ATELIER · EST. 2012';
  const headline = p.headline || '时间从不辜负专注';
  const sub = p.sub || '每一件作品，都为百年而作';
  const bg = p.bg || '#101014';
  const ink = p.ink || '#F4EFE6';
  const gold = p.gold || '#C9A84C';
  const muted = p.muted || '#8E8878';

  const t = frame / fps;
  const vertical = H > W;

  const T = (s) => s * fps;
  const enter = (start, dur, dist, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.exp) });
    return { opacity: k, transform: `translateY(${(1 - k) * dist}px)` };
  };
  const growX = (start, dur, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.poly(2)) });
    return { transform: `scaleX(${k})` };
  };

  // 呼吸辉光：唯一环境动效，极缓循环（定格期仍呼吸）
  const breathe = 0.06 + 0.035 * (1 + Math.sin(t * 0.9)) / 2;
  const toRgba = (hex, a) => {
    const h = hex.replace('#', '');
    const full = h.length === 3 ? h.split('').map((c) => c + c).join('') : h;
    const n = parseInt(full, 16);
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
  };

  const borderTop = growX(0.2, 0.5, Easing.out(Easing.poly(3)));
  const borderBottom = growX(0.28, 0.5, Easing.out(Easing.poly(3)));
  const eyebrowStyle = enter(0.5, 0.45, 10, Easing.out(Easing.sin));
  const headlineStyle = enter(0.8, 0.9, 34, Easing.out(Easing.exp));
  const headlineSpacing = interpolate(frame, [T(0.8), T(1.7)], [W * 0.012, W * 0.004],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.exp) });
  const ruleTop = growX(1.8, 0.6, Easing.inOut(Easing.poly(2)));
  const ruleBottom = growX(1.92, 0.6, Easing.inOut(Easing.poly(2)));
  const subStyle = enter(2.2, 0.55, 12, Easing.inOut(Easing.sin));

  const serif = "'Playfair Display', 'Noto Serif SC', 'Songti SC', serif";
  const sans = "'Inter', 'Noto Sans SC', sans-serif";
  const frameInset = Math.min(W, H) * 0.055;

  return (
    <div style={{ width: W, height: H, background: bg, position: 'relative', overflow: 'hidden', boxSizing: 'border-box' }}>
      {/* 中心暖光呼吸 */}
      <div style={{ position: 'absolute', left: '50%', top: '46%', width: W * 0.8, height: H * 0.8, transform: 'translate(-50%, -50%)', background: `radial-gradient(ellipse at center, ${toRgba(gold, breathe)} 0%, transparent 65%)`, opacity: 0.6 }} />

      {/* 上下金色细边框 */}
      <div style={{ position: 'absolute', top: frameInset, left: frameInset, right: frameInset, height: 1, background: gold, opacity: 0.75, transformOrigin: 'center', ...borderTop }} />
      <div style={{ position: 'absolute', bottom: frameInset, left: frameInset, right: frameInset, height: 1, background: gold, opacity: 0.75, transformOrigin: 'center', ...borderBottom }} />

      {/* 居中内容 */}
      <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: W * 0.1 }}>
        <div style={{ fontFamily: sans, fontSize: H * 0.022, letterSpacing: W * 0.012, color: gold, fontWeight: 500, textTransform: 'uppercase', opacity: eyebrowStyle.opacity, transform: eyebrowStyle.transform }}>{eyebrow}</div>
        <div style={{ width: W * 0.07, height: 1, background: gold, opacity: 0.9, margin: `${H * 0.045}px 0 ${H * 0.04}px`, transformOrigin: 'center', ...ruleTop }} />
        <div style={{ fontFamily: serif, fontSize: vertical ? W * 0.088 : H * 0.135, color: ink, fontWeight: 600, lineHeight: 1.18, textAlign: 'center', letterSpacing: `${headlineSpacing}px`, opacity: headlineStyle.opacity, transform: headlineStyle.transform }}>{headline}</div>
        <div style={{ width: W * 0.07, height: 1, background: gold, opacity: 0.9, margin: `${H * 0.045}px 0`, transformOrigin: 'center', ...ruleBottom }} />
        <div style={{ fontFamily: serif, fontSize: H * 0.034, color: muted, fontStyle: 'italic', letterSpacing: W * 0.003, opacity: subStyle.opacity, transform: subStyle.transform }}>{sub}</div>
      </div>
    </div>
  );
};

const MaximalistType = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 1280;
  const H = item.height || 720;

  const ghost = p.ghost || 'BREAK';
  const acts = [p.act1 || '全网首发', p.act2 || '首日破 10 万', p.act3 || '今晚 8 点 · 第二批开抢'];
  const chips = [p.chip1 || '00:00 开售', p.chip2 || '实时战报', p.chip3 || '限量 5000 份'];
  const ink = p.ink || '#101010';
  const paper = p.paper || '#FFFFFF';
  const red = p.red || '#E63946';
  const yellow = p.yellow || '#FFD60A';

  const t = frame / fps;
  const vertical = H > W;
  const act = t < 1.5 ? 0 : t < 3.0 ? 1 : 2;
  const actBg = [red, yellow, ink];
  const actInk = [paper, ink, paper];
  const heavy = '"Archivo Black", "ZCOOL QingKe HuangYou", sans-serif';
  const sans = '"Inter", "Noto Sans SC", sans-serif';
  const mainSize = vertical ? W * 0.13 : H * 0.17;

  const T = (s) => s * fps;

  // 幽灵词：0.15s back.out 弹入（scale 1.35→1，只入场一次）
  const ghostK = interpolate(frame, [T(0.15), T(0.65)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.back(1.6)) });
  const ghostScale = interpolate(frame, [T(0.15), T(0.65)], [1.35, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.back(1.6)) });

  // 主词：每幕 power4.in 从上方砸入
  const mainStart = [0.25, 1.55, 3.05][act];
  const mainK = interpolate(frame, [T(mainStart), T(mainStart + 0.28)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.in(Easing.poly(4)) });

  // 标签块：back.out 旋转弹入
  const chipStart = [0.55, 1.85, 3.35][act];
  const chipK = interpolate(frame, [T(chipStart), T(chipStart + 0.35)], [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.back(2.2)) });

  const ghostColor = act === 1 ? ink : paper;

  return (
    <div style={{ width: W, height: H, position: 'relative', overflow: 'hidden', boxSizing: 'border-box', background: actBg[act], color: actInk[act] }}>
      {/* 幽灵背景词 */}
      <div style={{
        position: 'absolute', left: '50%', top: '50%',
        transform: `translate(-50%, -50%) rotate(-4deg) scale(${ghostScale})`,
        fontFamily: heavy, fontSize: vertical ? W * 0.34 : H * 0.52,
        color: ghostColor, opacity: 0.14 * ghostK, whiteSpace: 'nowrap', letterSpacing: -W * 0.004
      }}>{ghost}</div>

      {/* 主词 + 标签 */}
      <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: H * 0.03, padding: W * 0.08 }}>
        <div style={{
          fontFamily: heavy, fontSize: mainSize, color: actInk[act], lineHeight: 1.1,
          textAlign: 'center', maxWidth: W * 0.86,
          opacity: mainK, transform: `translateY(${-(1 - mainK) * H * 0.09}px)`
        }}>{acts[act]}</div>
        <div style={{
          background: actInk[act], color: actBg[act], fontFamily: sans, fontSize: H * 0.032,
          fontWeight: 700, padding: `${H * 0.012}px ${W * 0.02}px`,
          transform: `rotate(${-8 + 6 * chipK}deg) scale(${0.7 + 0.3 * chipK})`, opacity: chipK
        }}>{chips[act]}</div>
      </div>
    </div>
  );
};

const LogoOutro = ({item}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const p = item.props || {};
  const W = item.width || 1280;
  const H = item.height || 720;

  const name = p.name || 'MOUNTAIN COFFEE';
  const cta = p.cta || '关注我们 · 每周一支产地视频';
  const subLine = p.subLine || 'EST. 2026';
  const bg = p.bg || '#0C0F12';
  const ink = p.ink || '#F5F7FA';
  const accent = p.accent || '#6CF3C0';
  const muted = p.muted || '#8A94A0';

  const words = String(name).split(' ');

  const T = (s) => s * fps;
  const enter = (start, dur, dist, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.exp) });
    return { opacity: k, transform: `translateY(${(1 - k) * dist}px)` };
  };
  const pop = (start, dur, from, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [from, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.exp) });
    return { opacity: k, transform: `scale(${k})` };
  };
  const growX = (start, dur, ease) => {
    const k = interpolate(frame, [T(start), T(start + dur)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease || Easing.out(Easing.poly(2)) });
    return { transform: `scaleX(${k})` };
  };

  // 词标逐件组装：每词 opacity 0→1 + y 46→0 + scale 0.92→1
  const wordItems = words.map((w, i) => {
    const start = 0.2 + i * 0.16;
    const k = interpolate(frame, [T(start), T(start + 0.5)], [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.exp) });
    return { word: w, opacity: k, transform: `translateY(${(1 - k) * 46}px) scale(${0.92 + 0.08 * k})` };
  });
  const dotStart = 0.2 + words.length * 0.16 + 0.05;
  const dotStyle = pop(dotStart, 0.35, 0, Easing.out(Easing.back(2)));
  const subStyle = enter(1.1, 0.4, 14, Easing.out(Easing.poly(2)));
  const ctaStyle = enter(2.6, 0.45, 18, Easing.out(Easing.poly(3)));
  const ctaRule = growX(2.7, 0.4, Easing.out(Easing.poly(2)));

  // 辉光只呼吸一次（1.7→2.05 升至 0.55，2.05→2.75 回落到 0.12），之后定格不再循环
  const glowOpacity = (() => {
    if (frame < T(1.7)) return 0;
    if (frame < T(2.05)) return interpolate(frame, [T(1.7), T(2.05)], [0, 0.55],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.poly(2)) });
    if (frame < T(2.75)) return interpolate(frame, [T(2.05), T(2.75)], [0.55, 0.12],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.poly(2)) });
    return 0.12;
  })();

  const serif = "'Playfair Display', 'Noto Serif SC', 'Songti SC', serif";

  return (
    <div style={{ width: W, height: H, position: 'relative', background: bg, color: ink, fontFamily: serif, overflow: 'hidden' }}>
      <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'baseline' }}>
          {wordItems.map((w, i) => (
            <span key={i}>
              <span style={{ fontSize: 84, fontWeight: 700, letterSpacing: '0.06em', opacity: w.opacity, transform: w.transform }}>{w.word}</span>
              {i < words.length - 1 && (
                <span style={{ fontSize: 84, color: accent, margin: '0 18px', opacity: dotStyle.opacity, transform: dotStyle.transform }}>·</span>
              )}
            </span>
          ))}
        </div>
        {subLine.length > 0 && (
          <div style={{ marginTop: 16, fontSize: 20, letterSpacing: '0.4em', color: muted, opacity: subStyle.opacity, transform: subStyle.transform }}>{subLine}</div>
        )}
        <div style={{ width: 120, height: 2, background: accent, margin: '34px 0 22px', transformOrigin: 'center center', ...ctaRule }} />
        <div style={{ fontSize: 26, letterSpacing: '0.12em', opacity: ctaStyle.opacity, transform: ctaStyle.transform }}>{cta}</div>
      </div>
      {/* 辉光层：中心径向渐变，透明度一次性呼吸 */}
      <div style={{ position: 'absolute', inset: 0, opacity: glowOpacity, pointerEvents: 'none', background: `radial-gradient(ellipse ${W * 0.5}px ${H * 0.42}px at 50% 46%, ${accent}26 0%, transparent 70%)` }} />
    </div>
  );
};
